 public static function activate($network_wide){if(!is_multisite()){deactivate_plugins(plugin_basename(ZCCNG_FILE));wp_die('Multisite required.');}self::sync_roles();self::install_site();update_option('zccng_schema_version',ZCCNG_VERSION,false);update_site_option('zccng_version',ZCCNG_VERSION);update_site_option('zccng_immersive_mode',1);if(!get_site_option('zccng_clock_layout'))update_site_option('zccng_clock_layout','split');}
 public static function sync_roles(){foreach(self::ROLES as $slug=>$def){$role=get_role($slug);if(!$role)$role=add_role($slug,$def[0],['read'=>true]);if($role)foreach($def[1] as $cap)$role->add_cap($cap);}if($admin=get_role('administrator'))foreach(self::all_caps() as $cap)$admin->add_cap($cap);}
 public static function all_caps(){$caps=[];foreach(self::ROLES as $def)$caps=array_merge($caps,$def[1]);return array_values(array_unique($caps));}
 public static function maybe_install_site(){if(get_option('zccng_schema_version')===ZCCNG_VERSION)return;self::install_site();update_option('zccng_schema_version',ZCCNG_VERSION,false);}
 public static function initialize_site($site){switch_to_blog((int)$site->blog_id);self::sync_roles();self::install_site();update_option('zccng_schema_version',ZCCNG_VERSION,false);restore_current_blog();}
