ser_id,created_at),KEY event_type(event_type)) $c;");dbDelta("CREATE TABLE {$wpdb->base_prefix}zccng_connected_sites (id bigint unsigned NOT NULL AUTO_INCREMENT,site_name varchar(191) NOT NULL,site_url varchar(255) NOT NULL,status varchar(30) NOT NULL DEFAULT 'pending',last_seen datetime NULL,PRIMARY KEY(id),UNIQUE KEY site_url(site_url(191))) $c;");}
